// flagKEMKey names a local ML-KEM key generated by gen-kem-key.
const (
	flagKEMKey       = "kem-key"
	flagKEMAlgorithm = "algorithm"
)

// kemKeyPaths are where gen-kem-key stores a key pair under <home>/pqc.
func kemKeyPaths(home, name string) (secret, public string) {
	base := filepath.Join(home, "pqc", name+".mlkem1024")
	return base, base + ".pub"
}

// GetCmdGenKEMKey generates an ML-KEM-1024 key pair locally. The secret key
// never leaves the machine; only the public key is published on chain.
func GetCmdGenKEMKey() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "gen-kem-key [name]",
		Short: "Generate and store an ML-KEM-1024 key pair for receiving encrypted data",
		Long: `Generate an ML-KEM-1024 (FIPS 203) key pair, store the secret key under
<home>/pqc/<name>.mlkem1024 (mode 0600) and the public key next to it as
<name>.mlkem1024.pub, and print the public key hex.

This is an encryption key, not a signing key: publish it with register-kem-key
so others can encrypt to your account. Keep the secret key: whatever was
encrypted to the published key can only be read with it.`,
		Args: cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			clientCtx, err := client.GetClientQueryContext(cmd)
			if err != nil {
				return err
			}
			secretPath, publicPath := kemKeyPaths(clientCtx.HomeDir, args[0])
			if _, err := os.Lstat(secretPath); err == nil {
				return fmt.Errorf("%s already exists; replacing it would make everything encrypted to its "+
					"public key unreadable. Pick another name", secretPath)
			}
			pk, sk, err := qpqc.MLKEM1024.Keygen()
			if err != nil {
				return fmt.Errorf("ml-kem keygen: %w", err)
			}
			if err := os.MkdirAll(filepath.Dir(secretPath), 0o700); err != nil {
				return err
			}
			if err := writeNewFile(secretPath, []byte(hex.EncodeToString(sk)), 0o600); err != nil {
				return err
			}
			if err := writeNewFile(publicPath, []byte(hex.EncodeToString(pk)), 0o644); err != nil {
				return err
			}
			fmt.Fprintf(cmd.OutOrStdout(), "stored ML-KEM-1024 secret key: %s\n", secretPath)
			fmt.Fprintf(cmd.OutOrStdout(), "public_key_hex: %s\n", hex.EncodeToString(pk))
			fmt.Fprintf(cmd.OutOrStdout(), "\npublish it on-chain:\n  qorechaind tx pqc register-kem-key --kem-key %s --from <key> --generate-only > kem.json\n"+
				"  qorechaind tx pqc cosign kem.json --from <key> --pqc-key <mldsa-key>\n", args[0])
			return nil
		},
	}
	flags.AddQueryFlagsToCmd(cmd)
	return cmd
}

// writeNewFile writes a file that must not exist yet.
func writeNewFile(path string, bz []byte, mode os.FileMode) error {
	f, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, mode)
	if err != nil {
		return err
	}
	if _, err := f.Write(bz); err != nil {
		f.Close()
		return err
	}
	if err := f.Sync(); err != nil {
		f.Close()
		return err
	}
	return f.Close()
}

// GetCmdRegisterKEMKey returns the command that publishes the account's KEM
// key.
//
// The message needs the account's hybrid signature, so on a network that
// requires it the transaction is produced with --generate-only and cosigned.
func GetCmdRegisterKEMKey() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "register-kem-key [pubkey-hex]",
		Short: "Publish your ML-KEM encryption public key so others can encrypt to your account",
		Long: `Publish a key-encapsulation (ML-KEM, FIPS 203) public key for your account.
Anyone can then read it (query pqc kem-key, REST /qorechain/pqc/v1/kem/{address},
JSON-RPC qor_getKEMKey) and encrypt to it.

The account must already hold a post-quantum signature key, and the transaction
needs its hybrid signature. Sending the command again replaces the published
key; remove-kem-key withdraws it. Give the key as hex, or with --kem-key name
to use one made by gen-kem-key.`,
		Example: `  qorechaind tx pqc gen-kem-key inbox
  qorechaind tx pqc register-kem-key --kem-key inbox --from me --generate-only > kem.json
  qorechaind tx pqc cosign kem.json --from me --pqc-key me-mldsa`,
		Args: cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			clientCtx, err := client.GetClientTxContext(cmd)
			if err != nil {
				return err
			}
			algoName, err := cmd.Flags().GetString(flagKEMAlgorithm)
			if err != nil {
				return err
			}
			algo, err := parseAlgorithmID(algoName)
			if err != nil {
				return err
			}
			keyName, err := cmd.Flags().GetString(flagKEMKey)
			if err != nil {
				return err
			}
			pub, err := kemPublicKeyArg(clientCtx.HomeDir, args, keyName)
			if err != nil {
				return err
			}
			msg := &types.MsgRegisterKEMKey{
				Sender:      clientCtx.GetFromAddress().String(),
				AlgorithmID: algo,
				PublicKey:   pub,
			}
			if err := msg.ValidateBasic(); err != nil {
				return err
			}
			return tx.GenerateOrBroadcastTxCLI(clientCtx, cmd.Flags(), msg)
		},
	}
	cmd.Flags().String(flagKEMAlgorithm, types.AlgorithmMLKEM1024.String(), "key-encapsulation algorithm (name or numeric id)")
	cmd.Flags().String(flagKEMKey, "", "use the public key of a key pair made by gen-kem-key")
	flags.AddTxFlagsToCmd(cmd)
	return cmd
}

// kemPublicKeyArg takes the public key from the argument or from a local key
// pair, exactly one of the two.
func kemPublicKeyArg(home string, args []string, keyName string) ([]byte, error) {
	switch {
	case len(args) == 1 && keyName != "":
		return nil, fmt.Errorf("give the public key either as an argument or with --%s, not both", flagKEMKey)
	case len(args) == 1:
		pub, err := hex.DecodeString(strings.TrimPrefix(args[0], "0x"))
		if err != nil {
			return nil, fmt.Errorf("invalid hex-encoded public key: %w", err)
		}
		return pub, nil
	case keyName != "":
		_, publicPath := kemKeyPaths(home, keyName)
		bz, err := os.ReadFile(publicPath)
		if err != nil {
			return nil, err
		}
		pub, err := hex.DecodeString(strings.TrimSpace(string(bz)))
		if err != nil {
			return nil, fmt.Errorf("%s: %w", publicPath, err)
		}
		return pub, nil
	default:
		return nil, fmt.Errorf("give the public key as an argument or with --%s", flagKEMKey)
	}
}

// GetCmdRemoveKEMKey returns the command that withdraws the account's KEM key.
func GetCmdRemoveKEMKey() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "remove-kem-key",
		Short: "Withdraw your published ML-KEM encryption public key",
		Long: `Withdraw the key-encapsulation public key your account published. Senders can
no longer read it from the chain. Data already encrypted to it stays readable
with the secret key. Needs the account's hybrid signature.`,
		Args: cobra.NoArgs,
		RunE: func(cmd *cobra.Command, _ []string) error {
			clientCtx, err := client.GetClientTxContext(cmd)
			if err != nil {
				return err
			}
			msg := &types.MsgRemoveKEMKey{Sender: clientCtx.GetFromAddress().String()}
			if err := msg.ValidateBasic(); err != nil {
				return err
			}
			return tx.GenerateOrBroadcastTxCLI(clientCtx, cmd.Flags(), msg)
		},
	}
	flags.AddTxFlagsToCmd(cmd)
	return cmd
}

// GetCmdQueryKEMKey returns the command that shows an address's published KEM
// key.
func GetCmdQueryKEMKey() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "kem-key [address]",
		Short: "Show the ML-KEM encryption public key an address published",
		Long:  `Show the key-encapsulation public key an address published, if any. The address is bech32 or 0x hex.`,
		Args:  cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			clientCtx, err := client.GetClientQueryContext(cmd)
			if err != nil {
				return err
			}
			res, err := types.NewQueryClient(clientCtx).KEMKey(cmd.Context(), &types.QueryKEMKeyRequest{Address: args[0]})
			if err != nil {
				return err
			}
			return clientCtx.PrintProto(res)
		},
	}
	flags.AddQueryFlagsToCmd(cmd)
	return cmd
}
